recipes.code:
{
  "inputs": [
    {
      "id": "fluf-api-token",
      "type": "promptString",
      "description": "Personal access token from https://fluf.io/connect/settings (Developer tab). Requires an active FLUF plan.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "fluf-mcp@0.1.2"
      ],
      "env": {
        "FLUF_API_TOKEN": "${input:fluf-api-token}",
        "FLUF_BASE_URL": "<fluf-base-url>"
      }
    }
  }
}
